def f(I):
    H=len(I); W=len(I[0])
    from collections import Counter
    cnt=Counter(x for r in I for x in r)
    bg=cnt.most_common(1)[0][0]
    cs=[c for c in cnt if c!=bg]
    b=None; o=None
    for b in cs:
        cl=[(i,j) for i in range(H) for j in range(W) if I[i][j]==b]
        rs={i for i,_ in cl}; cc={j for _,j in cl}
        if len(cl)==4 and len(rs)==2 and len(cc)==2:
            o=[c for c in cs if c!=b][0]; break
    bc=[(i,j) for i in range(H) for j in range(W) if I[i][j]==b]
    br=(min(i for i,_ in bc)+max(i for i,_ in bc))/2
    bc_c=(min(j for _,j in bc)+max(j for _,j in bc))/2
    ohl={(round(2*br-i),j) for i,j in [(i,j) for i in range(H) for j in range(W) if I[i][j]==o]}
    ovl={(round(2*bc_c-j),i) for i,j in [(i,j) for i in range(H) for j in range(W) if I[i][j]==o]}
